insert into public.pv_documents(id,title,country,agency,url,edition,topic,lifecycle,norm,legal_basis,applicability,source_status,published_on,effective_on,status) select 'au-tga-pv-responsibilities','Pharmacovigilance responsibilities of medicine sponsors','AU','AU_TGA','https://www.tga.gov.au/resources/guidance/pharmacovigilance-responsibilities-medicine-sponsors','Web guidance updated 2024-11-06','Sponsor PV responsibilities','Marketed','Guidance','Guidance explains Australian medicines legislation; check the cited Therapeutic Goods Act and current instruments.','Sponsors with medicines registered or listed on the ARTG. This guidance excludes unapproved clinical trial, Special Access Scheme and Authorised Prescriber medicines; read the source scope.','current','2012-11-10'::date,null,case when a.status='verified' and 'www.tga.gov.au'=any(a.domains) then 'active' else 'inactive' end from public.pv_agencies a where a.id='AU_TGA' on conflict(id)do nothing;
insert into public.pv_document_versions(document_id,revision,edition,source_url,source_status,published_on,effective_on,metadata,content_kind,capture_status) select id,1,edition,url,source_status,published_on,effective_on,to_jsonb(d),'metadata','metadata_only' from public.pv_documents d where id='au-tga-pv-responsibilities' and not exists(select 1 from public.pv_document_versions v where v.document_id=d.id);
insert into public.pv_documents(id,title,country,agency,url,edition,topic,lifecycle,norm,legal_basis,applicability,source_status,published_on,effective_on,status) select 'gb-mhra-pv-procedures','Guidance on pharmacovigilance procedures','GB','GB_MHRA','https://www.gov.uk/government/publications/guidance-on-pharmacovigilance-procedures/guidance-on-pharmacovigilance-procedures','Web guidance updated 2026-09-30','PV reporting and procedures','Marketed','Guidance','MHRA guidance explaining UK pharmacovigilance procedures; verify current legislation, product authorization and territorial arrangements.','UK marketing authorisation holders. Review the source and current guidance for distinctions affecting Great Britain, Northern Ireland and applicable authorisation routes.','current','2020-12-31'::date,null,case when a.status='verified' and 'www.gov.uk'=any(a.domains) then 'active' else 'inactive' end from public.pv_agencies a where a.id='GB_MHRA' on conflict(id)do nothing;
insert into public.pv_document_versions(document_id,revision,edition,source_url,source_status,published_on,effective_on,metadata,content_kind,capture_status) select id,1,edition,url,source_status,published_on,effective_on,to_jsonb(d),'metadata','metadata_only' from public.pv_documents d where id='gb-mhra-pv-procedures' and not exists(select 1 from public.pv_document_versions v where v.document_id=d.id);
insert into public.pv_documents(id,title,country,agency,url,edition,topic,lifecycle,norm,legal_basis,applicability,source_status,published_on,effective_on,status) select 'ca-hc-gvp-system','GUI-0102: Pharmacovigilance system','CA','CA_HC','https://www.canada.ca/en/health-canada/services/drugs-health-products/compliance-enforcement/good-manufacturing-practices/guidance-documents/pharmacovigilance-guidelines-0102/pharmacovigilance-system.html','GUI-0102 issued 2026-05-22','PV systems and quality','Marketed','Guidance','Health Canada administrative guidance, GUI-0102. Legislation prevails; read with the overview, regulations chapter, glossary and references.','Manufacturers and market authorization holders with in-scope marketed human drugs. This is one chapter, not the entire guideline. Confirm exclusions and the source overview.','current','2026-05-22'::date,'2026-05-22'::date,case when a.status='verified' and 'www.canada.ca'=any(a.domains) then 'active' else 'inactive' end from public.pv_agencies a where a.id='CA_HC' on conflict(id)do nothing;
insert into public.pv_document_versions(document_id,revision,edition,source_url,source_status,published_on,effective_on,metadata,content_kind,capture_status) select id,1,edition,url,source_status,published_on,effective_on,to_jsonb(d),'metadata','metadata_only' from public.pv_documents d where id='ca-hc-gvp-system' and not exists(select 1 from public.pv_document_versions v where v.document_id=d.id);
insert into public.pv_documents(id,title,country,agency,url,edition,topic,lifecycle,norm,legal_basis,applicability,source_status,published_on,effective_on,status) select 'ca-hc-gvp-regulations','GUI-0102: The regulations','CA','CA_HC','https://www.canada.ca/en/health-canada/services/drugs-health-products/compliance-enforcement/good-manufacturing-practices/guidance-documents/pharmacovigilance-guidelines-0102/regulations.html','GUI-0102 issued 2026-05-22','Postmarket reporting and records','Marketed','Guidance','Health Canada administrative guidance interpreting the Food and Drug Regulations; the chapter title does not make this guidance legislation. Read the current legal provisions.','Manufacturers and market authorization holders with in-scope marketed human drugs. This is one chapter, not the entire guideline. Read the overview, system chapter and qualifications.','current','2026-05-22'::date,'2026-05-22'::date,case when a.status='verified' and 'www.canada.ca'=any(a.domains) then 'active' else 'inactive' end from public.pv_agencies a where a.id='CA_HC' on conflict(id)do nothing;
